				`{"from":"source","to":"a"},{"from":"a","to":"report"},` +
				`{"from":"source","to":"b"},{"from":"b","to":"mid"},{"from":"mid","to":"report"}],` +
				`"total":1e400,"ratio":1e-400,"count":` + huge2 + `}`,
		},
